<?php
namespace App\Http\Controllers\Procurement;use App\Http\Controllers\Controller;use App\Models\{InventoryItem,PurchaseOrder,PurchaseRequisition,Store,Supplier};use App\Services\Procurement\ProcurementService;use Illuminate\Http\Request;use Illuminate\Support\Facades\DB;
class PurchaseOrderController extends Controller{public function index(){ $p=auth()->user()->property_id;return view('procurement.purchase-orders.index',['rows'=>PurchaseOrder::with(['supplier','store','items.inventoryItem'])->where('property_id',$p)->latest()->paginate(30),'suppliers'=>Supplier::where('property_id',$p)->where('is_active',1)->get(),'stores'=>Store::where('property_id',$p)->get(),'items'=>InventoryItem::where('property_id',$p)->where('is_active',1)->orderBy('name')->get(),'requisitions'=>PurchaseRequisition::where('property_id',$p)->where('status','approved')->get()]);}public function store(Request $r){$d=$r->validate(['supplier_id'=>'required|integer','store_id'=>'nullable|integer','purchase_requisition_id'=>'nullable|integer','expected_date'=>'nullable|date','inventory_item_id'=>'required|array|min:1','inventory_item_id.*'=>'required|integer','quantity'=>'required|array','quantity.*'=>'required|numeric|min:.0001','unit_cost'=>'required|array','unit_cost.*'=>'required|numeric|min:0','tax_rate'=>'nullable|array']);DB::transaction(function()use($d){$p=auth()->user()->property_id;$po=PurchaseOrder::create(['property_id'=>$p,'supplier_id'=>$d['supplier_id'],'store_id'=>$d['store_id']??null,'purchase_requisition_id'=>$d['purchase_requisition_id']??null,'number'=>'PO-'.now()->format('Ymd-His').'-'.random_int(10,99),'order_date'=>today(),'expected_date'=>$d['expected_date']??null,'created_by'=>auth()->id()]);$sub=$tax=0;foreach($d['inventory_item_id'] as $i=>$id){$q=(float)$d['quantity'][$i];$c=(float)$d['unit_cost'][$i];$rate=(float)($d['tax_rate'][$i]??0);$line=$q*$c;$sub+=$line;$tax+=$line*$rate/100;$po->items()->create(['inventory_item_id'=>$id,'quantity'=>$q,'unit_cost'=>$c,'tax_rate'=>$rate,'line_total'=>$line]);}$po->update(['subtotal'=>$sub,'tax_amount'=>$tax,'total_amount'=>$sub+$tax]);});return back()->with('success','Purchase order created.');}public function approve(PurchaseOrder $purchaseOrder,ProcurementService $svc){abort_unless($purchaseOrder->property_id===auth()->user()->property_id,403);$svc->approveOrder($purchaseOrder,auth()->id());return back()->with('success','Purchase order approved.');}}